CREATE FUNCTION "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_predecessor"(token_text text) RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE v uuid; n integer;
BEGIN
 SELECT count(*),min(predecessor::text)::uuid INTO n,v FROM "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_candidates" WHERE token=token_text::uuid;
 IF n<>1 THEN RAISE EXCEPTION 'ORM candidate predecessor not unique'; END IF;
 RETURN v;
END
$$

CREATE FUNCTION "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_deleted_version"(key_text text,predecessor_text text) RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE v uuid; n integer;
BEGIN
 SELECT count(*),min(token::text)::uuid INTO n,v FROM "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_candidates"
 WHERE key=key_text AND predecessor=predecessor_text::uuid AND action='DELETE';
 IF n<>1 THEN RAISE EXCEPTION 'ORM delete candidate not unique'; END IF;
 RETURN v;
END
$$

CREATE FUNCTION "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_before_fn"() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE k text; previous uuid; was_present boolean; v uuid; old_data jsonb; new_data jsonb;
BEGIN
 IF TG_OP<>'DELETE' THEN
  IF NEW.id IS NULL OR NEW.email IS NULL OR NEW.hashed_password IS NULL OR NEW.is_active IS NULL OR NEW.is_superuser IS NULL OR NEW.is_verified IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'ORM fixed UUID mutation unsupported'; END IF;
  k:=NEW.id::text;
 ELSE k:=OLD.id::text; END IF;
 SELECT token,present INTO previous,was_present FROM "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_state" WHERE key=k FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ORM key outside controlled fixed domain'; END IF;
 IF TG_OP<>'INSERT' AND (NOT was_present OR previous IS DISTINCT FROM OLD."_mtw_orm_version") THEN RAISE EXCEPTION 'ORM source chain mismatch'; END IF;
 v:=gen_random_uuid();
 old_data:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object('id',OLD."id"::text,'email',OLD."email",'hashed_password',OLD."hashed_password",'is_active',OLD."is_active",'is_superuser',OLD."is_superuser",'is_verified',OLD."is_verified") END;
 new_data:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('id',NEW."id"::text,'email',NEW."email",'hashed_password',NEW."hashed_password",'is_active',NEW."is_active",'is_superuser',NEW."is_superuser",'is_verified',NEW."is_verified") END;
 INSERT INTO "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_candidates"(token,key,predecessor,action,old_present,new_present,old_image,new_image)
 VALUES(v,k,previous,TG_OP,was_present,TG_OP<>'DELETE',old_data,new_data);
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE NEW."_mtw_orm_version":=v; RETURN NEW; END IF;
END
$$

CREATE FUNCTION "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_after_fn"() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE k text; v uuid; candidate record; n integer; actual_image jsonb;
BEGIN
 IF TG_OP='DELETE' THEN k:=OLD.id::text; v:="mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_deleted_version"(k,OLD."_mtw_orm_version"::text); actual_image:=NULL;
 ELSE k:=NEW.id::text; v:=NEW."_mtw_orm_version"; actual_image:=jsonb_build_object('id',NEW."id"::text,'email',NEW."email",'hashed_password',NEW."hashed_password",'is_active',NEW."is_active",'is_superuser',NEW."is_superuser",'is_verified',NEW."is_verified"); END IF;
 SELECT * INTO candidate FROM "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_candidates" WHERE token=v;
 IF NOT FOUND OR candidate.key IS DISTINCT FROM k OR candidate.action IS DISTINCT FROM TG_OP OR candidate.new_image IS DISTINCT FROM actual_image THEN RAISE EXCEPTION 'ORM actual effect candidate mismatch'; END IF;
 IF TG_OP='INSERT' AND candidate.old_present THEN RAISE EXCEPTION 'ORM insert source presence drift'; END IF;
 UPDATE "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_state" SET token=v,present=(TG_OP<>'DELETE'),image=actual_image
 WHERE key=k AND token=candidate.predecessor AND present=candidate.old_present;
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'ORM actual effect chain mismatch'; END IF;
 INSERT INTO "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_effects" SELECT * FROM "mtw_orm_v3_3a8f4a1188a4"."_mtw_orm_candidates" WHERE token=v;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END
$$

